-- Step 3b-0 (decided 2026-10-13). Generated by drizzle-kit, then HAND-EDITED
-- (marked "HAND-EDITED" below) for one reason: session_exercises.name is
-- NOT NULL, and drizzle-kit writes `ADD COLUMN "name" varchar(255) NOT NULL`
-- — which fails on any table that already has rows (every existing row would
-- start with a NULL name). So: add it nullable, fill it, then make it NOT
-- NULL. Same pattern as sessions.local_date in 0024.
--
-- 1. The foreign key from session_exercises to the program exercise gets a
--    short name. Drizzle's old name was 70 characters; Postgres cut it to 63
--    when creating it ("…_assigned_program"). The DROP below spells the full
--    name and still works: Postgres cuts identifiers in every command the
--    same way (with a NOTICE), so it names the same, cut, constraint.
ALTER TABLE "session_exercises" DROP CONSTRAINT "session_exercises_assigned_program_exercise_id_assigned_program_exercises_id_fk";
--> statement-breakpoint
-- 2. Retiring a program exercise (removed from the program, kept for the
--    sessions that used it): when, and by whom — both or neither.
ALTER TABLE "assigned_program_exercises" ADD COLUMN "retired_at" timestamp with time zone;--> statement-breakpoint
ALTER TABLE "assigned_program_exercises" ADD COLUMN "retired_by" integer;--> statement-breakpoint
-- 3. Each session keeps a COPY of what was prescribed when it started.
--    HAND-EDITED: "name" added WITHOUT NOT NULL here (see the top).
ALTER TABLE "session_exercises" ADD COLUMN "name" varchar(255);--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "sets" integer;--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "reps" integer;--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "duration_in_seconds" integer;--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "weight" real;--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "weight_unit" "weight_unit";--> statement-breakpoint
ALTER TABLE "session_exercises" ADD COLUMN "notes" text;--> statement-breakpoint
-- HAND-EDITED: the backfill. Existing rows get the program exercise's
-- prescription AS IT IS TODAY — the best information there is: what it was
-- when each old session started was never stored (that's the gap this step
-- closes). From now on every row is copied at the moment its session starts.
-- A migration runs as the tables' owner, so row-level security doesn't hide
-- any row here.
UPDATE "session_exercises" AS se
SET "name" = pe."name",
    "sets" = pe."sets",
    "reps" = pe."reps",
    "duration_in_seconds" = pe."duration_in_seconds",
    "weight" = pe."weight",
    "weight_unit" = pe."weight_unit",
    "notes" = pe."notes"
FROM "assigned_program_exercises" AS pe
WHERE pe."id" = se."assigned_program_exercise_id";--> statement-breakpoint
-- HAND-EDITED: now every row has its name (the foreign key guarantees each
-- row found its program exercise, whose name is NOT NULL).
ALTER TABLE "session_exercises" ALTER COLUMN "name" SET NOT NULL;--> statement-breakpoint
ALTER TABLE "assigned_program_exercises" ADD CONSTRAINT "assigned_program_exercises_retired_by_users_id_fk" FOREIGN KEY ("retired_by") REFERENCES "public"."users"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
ALTER TABLE "session_exercises" ADD CONSTRAINT "session_exercises_program_exercise_fk" FOREIGN KEY ("assigned_program_exercise_id") REFERENCES "public"."assigned_program_exercises"("id") ON DELETE restrict ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "session_exercises_program_exercise_id_idx" ON "session_exercises" USING btree ("assigned_program_exercise_id");--> statement-breakpoint
ALTER TABLE "assigned_program_exercises" ADD CONSTRAINT "assigned_program_exercises_retired_together" CHECK (("assigned_program_exercises"."retired_at" IS NULL) = ("assigned_program_exercises"."retired_by" IS NULL));